    /**
    Input to this function is a string represented multiple groups for nested parentheses separated by spaces.
    For each of the group, output the deepest level of nesting of parentheses.
    E.g. (()()) has maximum two levels of nesting while ((())) has three.

    >>> parseNestedParens("(()()) ((())) () ((())()())")
    [2, 3, 1, 3]
     */
    public List<Integer> parseNestedParens(String paren_string) {

generation:
	List<Integer> depths = new ArrayList<>();

	char[] chars = paren_string.toCharArray();
	int maxDepth = 0, currDepth = 0;
	boolean inParen = false;

	for (char c : chars) {
	    if (c == '(') {
		inParen = true;
		if (currDepth > maxDepth)
		    maxDepth = currDepth;
	    }
	    else if (c == ')') {
		inParen = false;
		currDepth--;
	    }
	    else if (inParen)
		currDepth++;
	}
	depths.add(maxDepth);
	return depths;
    }
    public int[] solve(String[] strs) {
	List<Integer> depths = new ArrayList<>();

	for (String str : strs) {
	    depths.addAll(parseNestedParens(str));
	}
	int[] res = new int[depths.size()];
	for (int i = 0; i < depths.size(); i++) {
	    res[i] = depths.get(i);
	}
	return res;
    }

    public static void main(String[] args) {
	Solution sol = new Solution();
	System.out.println(Arrays.toString(sol.solve(new String[] {"((()))","(()(()))","((()())","(()))","(((())))","(((()(())))" } )));
