    Find the lexicographically smallest string that can be formed by rearranging s.
    >>> smallestRotation("cabdc")
    "abc"
    >>> smallestRotation("cdab")
    "abcd"
     */
    public String smallestRotation(String s) {
	if (s == null || s.length() == 0) return "";
	char[] arr = s.toCharArray();
	Arrays.sort(arr);
	String smallest = new String(arr);
	for (int i = 0; i < arr.length; i++) {
